/**
 * Strategic facility / military base domain types.
 *
 * One record per real, publicly documented facility: overseas and domestic
 * bases, missile/early-warning/space sites, nuclear complex sites and
 * maritime chokepoints. Data is generated by scripts/build-facilities.py
 * from research agent output into ./strategic-facilities.generated.ts.
 */

export const FACILITY_TYPES = [
  "air_base",
  "naval_base",
  "army_base",
  "missile_site",
  "radar_site",
  "space_facility",
  "nuclear_facility",
  "intel_site",
  "logistics_hub",
  "chokepoint",
  "defense_industry",
] as const;

export type FacilityType = (typeof FACILITY_TYPES)[number];

export interface StrategicFacility {
  id: string;
  name: string;
  nameRu: string;
  type: FacilityType;
  /** ISO3 of the country operating the facility. */
  operator: string;
  /** ISO3 of the host country (equals operator for domestic sites; "INTL" for chokepoints). */
  hostIso: string;
  hostName: string;
  lat: number;
  lng: number;
  /** 1-10 strategic importance for map styling and ranking. */
  strategicValue: number;
  note: string;
  noteRu: string;
  source: string;
}

export const FACILITY_TYPE_LABELS_RU: Readonly<Record<FacilityType, string>> = {
  air_base: "Авиабаза",
  naval_base: "ВМБ",
  army_base: "Сухопутная база",
  missile_site: "Ракетный объект",
  radar_site: "РЛС / СПРН",
  space_facility: "Космический объект",
  nuclear_facility: "Ядерный объект",
  intel_site: "Разведка / РЭБ",
  logistics_hub: "Логистический узел",
  chokepoint: "Пролив / узкость",
  defense_industry: "ОПК",
};

export function isFacilityType(value: string): value is FacilityType {
  return (FACILITY_TYPES as readonly string[]).includes(value);
}

export const CONFLICT_ZONE_TYPES = [
  "war",
  "insurgency",
  "tension",
  "frozen",
  "maritime_dispute",
] as const;

export type ConflictZoneType = (typeof CONFLICT_ZONE_TYPES)[number];

/** Live conflict / tension zone for map overlay (distinct from historical /api/conflicts). */
export interface ConflictZone {
  id: string;
  name: string;
  nameRu: string;
  type: ConflictZoneType;
  /** 1-10 current intensity, drives ring styling. */
  intensity: number;
  /** ISO3 parties involved. */
  parties: string[];
  lat: number;
  lng: number;
  /** Approximate theatre radius for the overlay ring. */
  radiusKm: number;
  since: string;
  note: string;
  noteRu: string;
  source: string;
}

export const CONFLICT_TYPE_LABELS_RU: Readonly<Record<ConflictZoneType, string>> = {
  war: "Война",
  insurgency: "Повстанческий конфликт",
  tension: "Напряжённость",
  frozen: "Замороженный конфликт",
  maritime_dispute: "Морской спор",
};
